-- Function: public.fn_get_experience_harvest_requests
-- Backup generated on 2026-10-25 20:33:20

CREATE OR REPLACE FUNCTION public.fn_get_experience_harvest_requests(p_organization_id uuid DEFAULT NULL::uuid, p_status character varying DEFAULT NULL::character varying)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, source_experience_id uuid, source_version_number integer, license_id uuid, submitted_by_user_id uuid, submitted_at timestamp with time zone, status character varying, review_notes text, reviewed_by_user_id uuid, reviewed_at timestamp with time zone, safety_suitability_verified boolean, learning_objectives_verified boolean, instructions_verified boolean, materials_verified boolean, media_rights_verified boolean, commercial_rights_verified boolean, source_experience_title character varying, organization_name character varying, submitter_email character varying)  LANGUAGE sql  STABLE AS $function$     SELECT r.id AS id, r.tenant_id AS tenant_id, r.organization_id AS organization_id, r.source_experience_id AS source_experience_id,            r.source_version_number AS source_version_number, r.license_id AS license_id, r.submitted_by_user_id AS submitted_by_user_id,            r.submitted_at AS submitted_at, r.status AS status, r.review_notes AS review_notes, r.reviewed_by_user_id AS reviewed_by_user_id,            r.reviewed_at AS reviewed_at, r.safety_suitability_verified AS safety_suitability_verified,            r.learning_objectives_verified AS learning_objectives_verified, r.instructions_verified AS instructions_verified,            r.materials_verified AS materials_verified, r.media_rights_verified AS media_rights_verified,            r.commercial_rights_verified AS commercial_rights_verified,            e.title AS source_experience_title, o.name AS organization_name, u.email AS submitter_email     FROM experience_harvest_requests r     LEFT JOIN experiences e ON r.source_experience_id = e.id     LEFT JOIN organizations o ON r.organization_id = o.id     LEFT JOIN users u ON r.submitted_by_user_id = u.id     WHERE (p_organization_id IS NULL OR r.organization_id = p_organization_id)       AND (p_status IS NULL OR r.status = p_status)     ORDER BY r.submitted_at DESC; $function$ ;
